function arrayToUint8Array(arrayOfStrings, encoding = 'utf-8') {
    // Tính tổng độ dài bytes trước để allocate Uint8Array
    let totalLength = 0;
    const buffers = arrayOfStrings.map(str => Buffer.from(str, encoding));
    buffers.forEach(buf => { totalLength += buf.length; });

    // Tạo Uint8Array lớn
    const result = new Uint8Array(totalLength);
    let offset = 0;
    buffers.forEach(buf => {
        result.set(buf, offset);
        offset += buf.length;
    });

    return result;
}


