const crypto = require('crypto');

function aesEncrypt(input) {
    try {
        if (!(input instanceof Buffer)) {
            input = Buffer.from(input);
        }
        const keyHex = '6b714931445463774b5839305a744179';
        const key = Buffer.from(keyHex, 'hex');

        // Kiểm tra độ dài input phải bội số của 16 (block size AES), nếu không return empty như code gốc
        if (input.length === 0 || input.length % 16 !== 0) {
            throw new Error('Invalid input length');
        }

        // Tạo cipher AES-128-ECB, no padding
        const cipher = crypto.createCipheriv('aes-128-ecb', key, null);
        cipher.setAutoPadding(false);

        // Encrypt
        let encrypted = cipher.update(input);
        encrypted = Buffer.concat([encrypted, cipher.final()]);

        // Append 4 bytes độ dài input (big-endian)
        const len = input.length;
        const lenBytes = Buffer.alloc(4);
        lenBytes.writeUInt32BE(len, 0);

        return new Uint8Array(Buffer.concat([encrypted, lenBytes]));
    } catch (error) {
        // Nếu error (ví dụ length invalid), return empty Uint8Array
        console.error(error); // Optional: log error
        return new Uint8Array(0);
    }
}

function padPKCS7(data) {
    const blockSize = 16;
    const padLength = blockSize - (data.length % blockSize);
    const padded = new Uint8Array(data.length + padLength);
    padded.set(data);
    for (let i = data.length; i < padded.length; i++) {
        padded[i] = padLength;
    }
    return padded;
}
function i(n) {
    for (var e = n.length, r = new Uint8Array(e), o = 0; o < e; o++)
        r[o] = n.charCodeAt(o);
    return r
}

